k = input(7, "K Neighbors", 1, 15, 1)
FeatureBars = input(20, "Feature Bars", 5, 40, 1)
SearchBack = input(200, "Search Back", 50, 500, 10)
MarginThresh = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
DisagreeThresh = input(0.5, "Disagreement Threshold", 0.1, 2.0, 0.05)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Model calculations ───
ch = (close - open) / open
rg = (high - low) / open

chMean = sma(ch, SearchBack)
chSd = stdev(ch, SearchBack)
rgMean = sma(rg, SearchBack)
rgSd = stdev(rg, SearchBack)
chSdA = chSd + 0.000001
rgSdA = rgSd + 0.000001

availBars = bar_index - FeatureBars - 2
effBack = SearchBack
if availBars < effBack {
    effBack := availBars
}
if effBack < 8 {
    effBack := 8
}

bd0 = 999999.0
bd1 = 999999.0
bd2 = 999999.0
bd3 = 999999.0
bd4 = 999999.0
bd5 = 999999.0
bd6 = 999999.0
bt0 = 0
bt1 = 0
bt2 = 0
bt3 = 0
bt4 = 0
bt5 = 0
bt6 = 0

p = 2
while p < effBack {
    dist = 0.0
    f = 0
    while f < FeatureBars {
        curCh = (ch[f] - chMean) / chSdA
        pastCh = (ch[p + f] - chMean) / chSdA
        diffC = curCh - pastCh
        curRg = (rg[f] - rgMean) / rgSdA
        pastRg = (rg[p + f] - rgMean) / rgSdA
        diffR = curRg - pastRg
        dist := dist + diffC * diffC + diffR * diffR
        f := f + 1
    }
    dist := sqrt(dist)
    tgt = 0 - 1
    if close[p - 1] > close[p] {
        tgt := 1
    }
    if dist < bd0 {
        bd6 := bd5
        bt6 := bt5
        bd5 := bd4
        bt5 := bt4
        bd4 := bd3
        bt4 := bt3
        bd3 := bd2
        bt3 := bt2
        bd2 := bd1
        bt2 := bt1
        bd1 := bd0
        bt1 := bt0
        bd0 := dist
        bt0 := tgt
    } else {
        if dist < bd1 {
            bd6 := bd5
            bt6 := bt5
            bd5 := bd4
            bt5 := bt4
            bd4 := bd3
            bt4 := bt3
            bd3 := bd2
            bt3 := bt2
            bd2 := bd1
            bt2 := bt1
            bd1 := dist
            bt1 := tgt
        } else {
            if dist < bd2 {
                bd6 := bd5
                bt6 := bt5
                bd5 := bd4
                bt5 := bt4
                bd4 := bd3
                bt4 := bt3
                bd3 := bd2
                bt3 := bt2
                bd2 := dist
                bt2 := tgt
            } else {
                if dist < bd3 {
                    bd6 := bd5
                    bt6 := bt5
                    bd5 := bd4
                    bt5 := bt4
                    bd4 := bd3
                    bt4 := bt3
                    bd3 := dist
                    bt3 := tgt
                } else {
                    if dist < bd4 {
                        bd6 := bd5
                        bt6 := bt5
                        bd5 := bd4
                        bt5 := bt4
                        bd4 := dist
                        bt4 := tgt
                    } else {
                        if dist < bd5 {
                            bd6 := bd5
                            bt6 := bt5
                            bd5 := dist
                            bt5 := tgt
                        } else {
                            if dist < bd6 {
                                bd6 := dist
                                bt6 := tgt
                            }
                        }
                    }
                }
            }
        }
    }
    p := p + 1
}

upVotes = 0
if bt0 == 1 { upVotes := upVotes + 1 }
if bt1 == 1 { upVotes := upVotes + 1 }
if bt2 == 1 { upVotes := upVotes + 1 }
if bt3 == 1 { upVotes := upVotes + 1 }
if bt4 == 1 { upVotes := upVotes + 1 }
if bt5 == 1 { upVotes := upVotes + 1 }
if bt6 == 1 { upVotes := upVotes + 1 }
downVotes = 7 - upVotes
marginRaw = (upVotes - downVotes) / 7.0

meanD = (bd0 + bd1 + bd2 + bd3 + bd4 + bd5 + bd6) / 7.0
v0 = (bd0 - meanD) * (bd0 - meanD)
v1 = (bd1 - meanD) * (bd1 - meanD)
v2 = (bd2 - meanD) * (bd2 - meanD)
v3 = (bd3 - meanD) * (bd3 - meanD)
v4 = (bd4 - meanD) * (bd4 - meanD)
v5 = (bd5 - meanD) * (bd5 - meanD)
v6 = (bd6 - meanD) * (bd6 - meanD)
sdD = sqrt((v0 + v1 + v2 + v3 + v4 + v5 + v6) / 7.0)
disagreeRaw = sdD / (meanD + 0.000001)

ready = bar_index > FeatureBars + 12 and effBack > 10 and bd6 < 999998.0
margin = marginRaw
disagree = disagreeRaw
if ready {
    margin := marginRaw
    disagree := disagreeRaw
}
if bd6 > 999998.0 {
    margin := 0.0
    disagree := 0.0
}

buyCond = margin >= MarginThresh and disagree <= DisagreeThresh
sellCond = margin <= (0 - MarginThresh) and disagree <= DisagreeThresh
contestedCond = abs(margin) >= MarginThresh and disagree > DisagreeThresh

buySig = buyCond and not buyCond[1] and ready
sellSig = sellCond and not sellCond[1] and ready

// ─── Signal markers (2D) ───
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}

// ─── Unconditional rendering (2D twins) ───
plot(margin, "Vote Margin", "#22cc88", 2, "separate")
plot(disagree, "Disagreement", "#ffd43b", 1, "separate")
hline(0, "#888888", "separate")
hline(DisagreeThresh, "#ff4477", "separate")
hline(MarginThresh, "#22cc88", "separate")
hline(0 - MarginThresh, "#ff4477", "separate")
if contestedCond {
    bgcolor("rgba(255,212,59,0.08)", "separate")
}

// ─── 3D form: prism height = margin, footprint layer = disagreement ───
plot3d(margin * 10, "Vote Margin Prism", "bars3d", "#b48cff", "separate")
plot3d(disagree * 5, "Disagreement Footprint", "ribbon", "#ffd43b", "separate", 1)
plot3d(DisagreeThresh * 5, "D Threshold Plane", "line3d", "#ff4477", "separate", 2)
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "separate")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 0, "separate")
}

// Visible Session Volume Profile Value Signal Model
// Volume-at-price bins over the visible session, POC + value-area expansion,
// breakout signals on leaving value. 2D carries POC/VAH/VAL always.

rows = input(24, "Rows", 5, 48, 1)
vaPct = input(70, "Value Area %", 50, 90, 5)
sessLen = input(120, "Session Length", 24, 300, 4)
extendLines = input(true, "Extend Lines")
showHist = input(true, "Show Value Histogram")
enable3D = input(true, "Enable 3D")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Visible session range ─────────────────────────────────────────
hh = highest(high, sessLen)
ll = lowest(low, sessLen)
rng = hh - ll
rngSafe = rng
if rngSafe <= 0 {
    rngSafe := close * 0.01
}
sessPos = bar_index % sessLen
isNewSession = sessPos == 0

// ─── Persistent per-bin volume (one visible session block) ─────────
var binVol = array()
var binInit = 0
if binInit == 0 {
    binInit := 1
}
if array.size(binVol) != rows {
    binVol := array()
    k = 0
    while k < rows {
        array.push(binVol, 0.0)
        k := k + 1
    }
}
if isNewSession {
    k = 0
    while k < rows {
        array.set(binVol, k, 0.0)
        k := k + 1
    }
}

// ─── Distribute current bar volume across overlapped bins ──────────
barRange = high - low
closeBin = floor((close - ll) / rngSafe * rows)
if closeBin < 0 {
    closeBin := 0
}
if closeBin > rows - 1 {
    closeBin := rows - 1
}
if barRange <= 0 {
    prev = array.get(binVol, closeBin)
    array.set(binVol, closeBin, prev + volume)
} else {
    b = 0
    while b < rows {
        binBot = ll + b / rows * rngSafe
        binTop = ll + (b + 1) / rows * rngSafe
        topEdge = high
        if binTop < topEdge {
            topEdge := binTop
        }
        botEdge = low
        if binBot > botEdge {
            botEdge := binBot
        }
        overlap = topEdge - botEdge
        if overlap > 0 {
            share = overlap / barRange
            prev = array.get(binVol, b)
            array.set(binVol, b, prev + volume * share)
        }
        b := b + 1
    }
}

// ─── POC = max-volume bin ──────────────────────────────────────────
pocBin = 0
pocVol = array.get(binVol, 0)
b = 1
while b < rows {
    v = array.get(binVol, b)
    if v > pocVol {
        pocVol := v
        pocBin := b
    }
    b := b + 1
}
totalVol = array.sum(binVol)
pocPrice = ll + (pocBin + 0.5) / rows * rngSafe
pocShare = 0.0
if totalVol > 0 {
    pocShare := pocVol / totalVol
}

// ─── Value area: expand from POC by higher-volume neighbor ─────────
vaLowBin = pocBin
vaHighBin = pocBin
accum = pocVol
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < rows {
    leftVal = 0 - 1.0
    if vaLowBin > 0 {
        leftVal := array.get(binVol, vaLowBin - 1)
    }
    rightVal = 0 - 1.0
    if vaHighBin < rows - 1 {
        rightVal := array.get(binVol, vaHighBin + 1)
    }
    if rightVal >= leftVal {
        if vaHighBin < rows - 1 {
            vaHighBin := vaHighBin + 1
            accum := accum + rightVal
        } else {
            if vaLowBin > 0 {
                vaLowBin := vaLowBin - 1
                accum := accum + leftVal
            } else {
                guard := rows
            }
        }
    } else {
        if vaLowBin > 0 {
            vaLowBin := vaLowBin - 1
            accum := accum + leftVal
        } else {
            if vaHighBin < rows - 1 {
                vaHighBin := vaHighBin + 1
                accum := accum + rightVal
            } else {
                guard := rows
            }
        }
    }
    guard := guard + 1
}
vahPrice = ll + (vaHighBin + 1) / rows * rngSafe
valPrice = ll + vaLowBin / rows * rngSafe
vaWidth = vahPrice - valPrice
insideVA = close >= valPrice and close <= vahPrice
insidePrev = close[1] >= valPrice[1] and close[1] <= vahPrice[1]

// ─── Value histogram weight for 2D twin ────────────────────────────
histWeight = 0.0
if totalVol > 0 {
    histWeight := totalVol / (totalVol + volume + 1)
}
histLine = close
if showHist {
    histLine := valPrice + vaWidth * histWeight + (pocShare - 0.5) * rngSafe * 0.1
}

// ─── 3D terrain height: price-denominated value ridge ──────────────
concentration = 0.0
if rngSafe > 0 {
    concentration := (pocShare - 0.5) * rngSafe
}
terrainH = pocPrice + concentration + (histWeight - 0.5) * rngSafe * 0.2

// ─── Signals: price leaving value ──────────────────────────────────
buySig = close > vahPrice and insidePrev and not insideVA
sellSig = close < valPrice and insidePrev and not insideVA
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 1, "3d")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 3, "3d")
}

// ─── POC rail label (rare: new session POC only) ───────────────────
if isNewSession {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 1, "3d")
}

// ─── 2D: same POC/VAH/VAL information when 3D is off ───────────────
plot(close, "Price", "#ffffff", 1)
pocLine = plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
vahLine = plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
valLine = plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(histLine, "Value Histogram", "#4488ff", 1)
fill(vahLine, valLine, "rgba(68,136,255,0.12)")
if not insideVA {
    bgcolor("rgba(255,136,0,0.05)")
}

// ─── 3D: value terrain + POC labelled rail + VAH/VAL plateau rails ─
plot3d(terrainH, "Value Terrain", "surface", "#4488ff", "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vahPrice, "VAH Rail", "line3d", "#22cc88", "3d", 2)

// FIX 1: var lvl = highest(high, 20) froze at bar 0 — plain assignment recomputes every bar.
// FIX 2: close[-1] reads a future bar — close tests the current breakout with no lookahead.
// FIX 3: plotshape(true, low, "Buy", shape.triangleup, color.green) is Pine — OakScript uses (bar_index, price, title, style, color) with quoted strings.
// FIX 4: RSI surface in pane="3d" buries price bars — oscillators must render in pane="separate".
lvl = highest(high, 20)
r = rsi(close, 14)
buySig = close > lvl
osSig = crossover(r, 30)
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot(r, "RSI", "#b48cff", 1)
plot3d(r, "RSI", "surface", "#b48cff", "separate")
